-- Alta masiva de la familia Exceline (issue #60): the 60 products of Emilio's
-- Lista_precios_Exceline_jun2026.xlsx, as the product form would file them: the
-- familia Exceline, unit Pieza, the pre-margin cost in MXN, no Peso and no SAT codes
-- (they show under "Sin datos para facturar" until someone captures them). Each
-- description is one paragraph, word for word as in the Excel, which already has
-- EXL-GSM-AS120BS and EXL-GSM-AS220BS corrected (Emilio, in the issue: the supplier's
-- list has them crossed) and the three EXL-GTC-B1C… timers he added.
--
-- Exceline was created in the app, so only databases that have it get the products;
-- elsewhere (a fresh dev database, the tests) this inserts nothing. A SKU that already
-- exists, deleted or in another case, is left exactly as it is, never overwritten.
--
-- New rows only, so the previous build keeps working and this isn't exclusive. They fire
-- the products audit trigger; log them as unattributed, so the Historial says "Sistema".
UPDATE audit_actor SET user_id = NULL, source = NULL WHERE id = 1;

WITH exceline (n, sku, description, cost_micros) AS (VALUES
    (1, 'EXL-GSM-N', 'Protector de voltaje para refrigeradores hasta 28 pies cúbicos. Ideal para refrigerador convencional y equipos Inverter, enfriadores de agua, congeladores domésticos, enfriadores de aire hasta 5000 BTU. Voltaje 120 V~, capacidad 10 amperios (1270 W).', 278550000),
    (2, 'EXL-GSM-MP', 'Protector de voltaje para electrodomésticos. Ideal para microondas, lavadoras, televisores, ayudante de cocina, aparatos electrodomésticos en general. Voltaje 120 V~, capacidad 12 amperios (1500 W).', 280350000),
    (3, 'EXL-GSM-E', 'Protector de voltaje para equipos electrónicos. Ideal para televisores, Smart TV, computadoras, impresoras, equipos de sonido, consolas de videojuegos, módems y routers. Aparatos electrónicos en general. Voltaje 120 V~, capacidad 12 amperios (1500 W). Salida de 3 contactos.', 289350000),
    (4, 'EXL-GSM-RE120A', 'Protector de voltaje para aire acondicionado y refrigeración. Ideal para refrigeradores y vitrinas enfriadoras hasta 72 pies cúbicos, minisplit, lavasecadoras, cocinas eléctricas, motores en general. 120 V~, 20 A, 1.0 HP (18000 BTU).', 396900000),
    (5, 'EXL-GSM-RE220M', 'Protector de voltaje para aire acondicionado y refrigeración. Ideal para refrigeradores y vitrinas enfriadoras hasta 72 pies cúbicos, minisplit, lavasecadoras, cocinas eléctricas, motores en general. 220 V~, 20 A, 2.0 HP (48000 BTU).', 375300000),
    (6, 'EXL-GSM-EP120A', 'Protector de voltaje para equipos electrónicos profesionales. Ideal para televisores Smart TV, sistemas de sonido y video profesional, microondas de mayor potencia, fotocopiadoras, impresoras láser, electrónicos en general. Incluye supresores de pico y filtro EMI contra ruidos de línea. Voltaje 120 V~, capacidad 20 amperios (2500 W). (El usuario puede añadir un multicontacto).', 412200000),
    (7, 'EXL-GSM-AS120BS', 'Protector de voltaje para aires minisplit o tipo consola. Recomendado para evitar daños en los minisplits cuando llega muy alto o bajo voltaje, intermitencias, apagones y picos. No afecta la apariencia estética del minisplit. 120 V, 20 A RLA, 18000 BTU.', 534600000),
    (8, 'EXL-GSM-AS220BS', 'Protector de voltaje para aires minisplit o tipo consola. Recomendado para evitar daños en los minisplits cuando llega muy alto o bajo voltaje, intermitencias, apagones y picos. No afecta la apariencia estética del minisplit. 220 V, 20 A RLA, 48000 BTU.', 534600000),
    (9, 'EXL-GTC-E120AS', 'Programador interruptor horario de alta carga (20 amperios). Para automatizar el encendido y apagado de equipos eléctricos, tales como minisplit, iluminación, bombas de agua, sistemas para riego, albercas y ornamentales, etc. Conexión con clavija y receptáculo. 120 V, 20 A (2500 W, 1.5 HP).', 397350000),
    (10, 'EXL-GTC-E220MS', 'Programador interruptor horario de alta carga (20 amperios). Para automatizar el encendido y apagado de equipos eléctricos, tales como minisplit, iluminación, bombas de agua, sistemas para riego, albercas y ornamentales, etc. Conexión con clavija y receptáculo. 220 V, 20 A (4400 W, 2 HP).', 397350000),
    (11, 'EXL-GTC-B1C120S', 'Programador horario de control para cargas eléctricas (conexión mediante bornera). Interruptor horario para automatizar el encendido y apagado de equipos eléctricos que trabajan con contactor, tales como aires acondicionados, sistemas de bombas, etc. 120 V~. Salida con contacto aislado SPDT, capacidad 3.5 A.', 438750000),
    (12, 'EXL-GTC-B1C220S', 'Programador horario de control para cargas eléctricas (conexión mediante bornera). Interruptor horario para automatizar el encendido y apagado de equipos eléctricos que trabajan con contactor, tales como aires acondicionados, sistemas de bombas, etc. 220 V~. Salida con contacto aislado SPDT, capacidad 3.5 A.', 438750000),
    (13, 'EXL-GTC-B1CMV', 'Programador horario de control para cargas eléctricas (conexión mediante bornera). Interruptor horario para automatizar el encendido y apagado de equipos eléctricos que trabajan con contactor, tales como aires acondicionados, sistemas de bombas, etc. Multivoltaje 120/220 V~. Salida con contacto aislado SPDT, capacidad 3.5 A.', 438750000),
    (14, 'EXL-GIQ-10A-1', 'Interruptor pastilla termomagnética para centro de carga. Protegen contra sobrecargas y cortocircuitos en las instalaciones eléctricas. 120/240 V~, poder de corte de 10 kA. Curva de disparo NEMA tipo C. 10 A, 1 polo.', 61650000),
    (15, 'EXL-GIQ-15A-1', 'Interruptor pastilla termomagnética para centro de carga. Protegen contra sobrecargas y cortocircuitos en las instalaciones eléctricas. 120/240 V~, poder de corte de 10 kA. Curva de disparo NEMA tipo C. 15 A, 1 polo.', 61650000),
    (16, 'EXL-GIQ-20A-1', 'Interruptor pastilla termomagnética para centro de carga. Protegen contra sobrecargas y cortocircuitos en las instalaciones eléctricas. 120/240 V~, poder de corte de 10 kA. Curva de disparo NEMA tipo C. 20 A, 1 polo.', 61650000),
    (17, 'EXL-GIQ-30A-1', 'Interruptor pastilla termomagnética para centro de carga. Protegen contra sobrecargas y cortocircuitos en las instalaciones eléctricas. 120/240 V~, poder de corte de 10 kA. Curva de disparo NEMA tipo C. 30 A, 1 polo.', 61650000),
    (18, 'EXL-GFE-MV3M', 'Flotador eléctrico para bomba de cisterna o tinaco 120/220 V~. Automatiza el encendido y apagado de bombas eléctricas de agua. Nivel de agua ajustable mediante contrapeso. Cable de 3 metros, 0.5 HP, 16 A máx., 4 A nominal.', 151650000),
    (19, 'EXL-GFE-MV5M', 'Flotador eléctrico para bomba de cisterna o tinaco 120/220 V~. Automatiza el encendido y apagado de bombas eléctricas de agua. Nivel de agua ajustable mediante contrapeso. Cable de 5 metros, 0.5 HP, 16 A máx., 4 A nominal.', 193950000),
    (20, 'EXL-GFE-MV7M', 'Flotador eléctrico para bomba de cisterna o tinaco 120/220 V~. Automatiza el encendido y apagado de bombas eléctricas de agua. Nivel de agua ajustable mediante contrapeso. Cable de 7 metros, 0.5 HP, 16 A máx., 4 A nominal.', 243450000),
    (21, 'EXL-GBP-060', 'Bomba periférica de agua. Bomba de alto rendimiento, con sistema anti bloqueo. Motor con carcasa exterior de aluminio para mejor disipación de calor. Eje encapsulado a prueba de contaminantes. Impulsor rotativo de bronce. 120 V~, 1/2 HP, caudal máx. 42 L/min o altura máx. 36 m.', 778050000),
    (22, 'EXL-GBP-065', 'Bomba periférica de agua. Bomba de alto rendimiento, con sistema anti bloqueo. Motor con carcasa exterior de aluminio para mejor disipación de calor. Eje encapsulado a prueba de contaminantes. Impulsor rotativo de bronce. 120 V~, 3/4 HP, caudal máx. 55 L/min o altura máx. 42 m.', 1033200000),
    (23, 'EXL-GBS-LA-750-S', 'Bomba sumergible de achique. Bomba con selector manual para 3 tipos de operación: aguas limpias, aguas sucias, lodos líquidos. Para limpieza de tanques, tinacos, cisternas, drenajes, patios inundados, trasvases. Alimentación 120 V~ 750 W (1.25 HP). Caudal máx. 12500 L/hora, o altura máx. 8 metros, o profundidad máx. 7 metros.', 1279800000),
    (24, 'EXL-GMP-R120', 'Moto protector para refrigerador enfriador de bebidas y alimentos. Regulador de voltaje para refrigerador que utiliza compresor fraccionario 1/3 HP o Inverter 1/2 HP. Rango de salida regulada: de 95 a 130 V~ / Rango de entrada regulable: de 72 a 150 V~. Ciclo de espera en el arranque: 3 min. Empaque hermético de policarbonato, a prueba de insectos, contaminantes, rociado de agua. Montaje y conexionado dentro del chasis del refrigerador: terminales FASTON hembra 0.250.', 1153800000),
    (25, 'EXL-GI208S', 'Supervisor de voltaje trifásico 220 V~. Relay auxiliar que protege contra fallas por sobre voltaje, bajo voltaje, desbalance, pérdida de fase y fases invertidas. Para equipos eléctricos trifásicos en general. Salida de relay, 1 polo tipo SPDT para circuito de control 3A@240V~ / 1.5A@480V~.', 1053450000),
    (26, 'EXL-GST-440', 'Supervisor de voltaje trifásico 440/480 V~. Relay auxiliar que protege contra fallas por sobre voltaje, bajo voltaje, desbalance, pérdida de fase y fases invertidas. Para equipos eléctricos trifásicos en general. Salida de relay, 1 polo tipo SPDT para circuito de control 3A@240V~ / 1.5A@480V~.', 1053450000),
    (27, 'EXL-GII+L208S', 'Relevador de protección contra fallas de fase. Supervisor trifásico que protege contra sobre voltaje, bajo voltaje, desbalance, pérdida de fase, fases invertidas, fluctuación de frecuencia Hz. Incluye un programador interruptor horario que se puede utilizar opcionalmente. Registra en su memoria los últimos 20 eventos de falla. Salida de relay, 1 polo tipo SPDT para control 3A@240V~ / 1.5A@480V~. Alimentación 220 V~.', 8397000000),
    (28, 'EXL-GII+L480S', 'Relevador de protección contra fallas de fase. Supervisor trifásico que protege contra sobre voltaje, bajo voltaje, desbalance, pérdida de fase, fases invertidas, fluctuación de frecuencia Hz. Incluye un programador interruptor horario que se puede utilizar opcionalmente. Registra en su memoria los últimos 20 eventos de falla. Salida de relay, 1 polo tipo SPDT para control 3A@240V~ / 1.5A@480V~. Alimentación 440/480 V~.', 8397000000),
    (29, 'EXL-GOCT20804S', 'Super térmico para motores trifásicos. Relay auxiliar de protección integral contra fallas de fases en el suministro eléctrico y sobrecargas térmicas en motores universales, bombas y compresores. Disparo clase térmica 10. Sustituye a los relés térmicos convencionales, y amplía de manera coordinada funciones contra fallas de voltaje. 208/220 V~, corriente a plena carga: 1.0 a 4.0 A.', 1529550000),
