INSERT INTO products (family_id, sku, description, cost_micros, unit_id)
SELECT f.id, e.sku, e.description, e.cost_micros, (SELECT id FROM units WHERE code = 'pza')
FROM exceline e
JOIN product_families f ON f.name = 'Exceline' COLLATE NOCASE AND f.free_lines_only = 0
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.sku = e.sku COLLATE NOCASE)
ORDER BY e.n;
